	// Make one chunk look finished and rebuild the external-reset path.
	auto it = world.chunks.find(Int32_2{ 0, 0 });
	CHECK(it != world.chunks.end());
	if (it != world.chunks.end())
		it->second->state.store(ChunkState::Generated);
