	entry.isMobile = true;
	entry.profile.updateFrequency = 1000;

	tracker.Update(entry);
	CHECK_EQ(tracker.equipmentUpdateCalls, size_t(1));
	CHECK_EQ(tracker.metadataUpdateCalls, size_t(0));
	CHECK_EQ(tracker.eventFlushCalls, size_t(0));

	for (int i = 0; i < 100; ++i)
		tracker.Update(entry);
