void TestEntityAabbQueries() {
	WorldManager world;
	EntityManager manager;
	manager.world = &world;
	EntityId nextId = 1;
	manager.nextEntityId = &nextId;

	auto add = [&](Vec3 pos, bool collidable) {
		auto entity = std::make_shared<Entity>();
		entity->type = EntityType::ITEM;
		entity->position = pos;
		entity->actsAsWorldCollider = collidable;
		manager.AddEntity(entity);
		return entity;
	};
	auto first = add({ 0.0, 0.0, 0.0 }, true);
	auto second = add({ 1.0, 0.0, 0.0 }, false);
	auto far = add({ 40.0, 0.0, 0.0 }, true);

	const AABB nearBox{ -0.5, -0.5, -0.5, 1.5, 1.5, 1.5 };
	std::vector<Entity*> out;
	out.reserve(8);
	const size_t capacity = out.capacity();
	for (int i = 0; i < 100; ++i)
		manager.GetEntitiesWithinAabb(nearBox, out);
	CHECK_EQ(out.size(), size_t(2));
	CHECK_EQ(out.capacity(), capacity);
	CHECK(std::find(out.begin(), out.end(), first.get()) != out.end());
	CHECK(std::find(out.begin(), out.end(), second.get()) != out.end());
	CHECK(std::find(out.begin(), out.end(), far.get()) == out.end());

	manager.GetEntitiesWithinAabbExcluding(nearBox, first->id, out);
	CHECK_EQ(out.size(), size_t(1));
	CHECK_EQ(out[0], second.get());

	EntityType itemType = EntityType::ITEM;
	manager.GetEntitiesWithinAabbOfType(nearBox, itemType, out);
	CHECK_EQ(out.size(), size_t(2));

	CHECK(manager.AnyEntityWithinAabb(nearBox));
	const AABB emptyBox{ 100.0, 100.0, 100.0, 101.0, 101.0, 101.0 };
	CHECK(!manager.AnyEntityWithinAabb(emptyBox));

	manager.GetCollidablesWithinAabb(nearBox, EntityId(-1), out);
	CHECK(std::find(out.begin(), out.end(), first.get()) != out.end());
	CHECK(std::find(out.begin(), out.end(), far.get()) == out.end());

	auto allocating = manager.GetEntitiesWithinAabb(nearBox);
	manager.GetEntitiesWithinAabb(nearBox, out);
	CHECK_EQ(allocating.size(), out.size());

	const AABB hugeBox{ -10000.0, -10000.0, -10000.0, 10000.0, 10000.0, 10000.0 };
	manager.GetEntitiesWithinAabb(hugeBox, out);
	CHECK_EQ(out.size(), size_t(3));
	CHECK(manager.AnyEntityWithinAabb(hugeBox));
}

void TestTrackerMassDespawn() {
	EntityTracker tracker;
	std::vector<std::unique_ptr<Entity>> dead;
	for (int i = 0; i < 1000; ++i) {
		auto entity = std::make_unique<Entity>();
		entity->id = EntityId(i + 1);
		entity->type = EntityType::ITEM;
		entity->position = { double(i % 16), 64.0, double(i / 16) };
		entity->isDead = true;
		TrackedEntry entry;
		entry.entity = entity.get();
		entry.profile.updateFrequency = INT_MAX;
		entry.lastSpawnCheckPosition = entity->position;
		tracker.trackedEntities[entity->id] = entry;
		dead.push_back(std::move(entity));
	}
	tracker.spawnStateDirty = false;
	tracker.Tick();
	CHECK(tracker.trackedEntities.empty());
	CHECK_EQ(tracker.staleVisibilityErases, size_t(0));
	CHECK_EQ(tracker.spawnPairChecks, size_t(0));

	EntityTracker staleTracker;
	Entity entity;
	entity.id = 2;
	entity.type = EntityType::ITEM;
	TrackedEntry entry;
	entry.entity = &entity;
	entry.profile.updateFrequency = INT_MAX;
	entry.visibleTo.insert(EntityId(999));
	entry.lastSpawnCheckPosition = entity.position;
	staleTracker.trackedEntities[entity.id] = entry;
	staleTracker.spawnStateDirty = false;
	staleTracker.Tick();
	CHECK(staleTracker.trackedEntities.at(entity.id).visibleTo.empty());
	CHECK_EQ(staleTracker.staleVisibilityErases, size_t(1));
}

