void TestTorchBurnoutWindow() {
	WorldManager world;
	world.elapsedTicks = 1000;
	RedstoneManager::PruneTorchUpdates(world);

	const Int3 pos{ 5, 64, 5 };
	const Int3 other{ 6, 64, 5 };
	for (int i = 0; i < 7; ++i) {
		CHECK(!RedstoneManager::CheckTorchBurnout(world, pos, true));
		CHECK(!RedstoneManager::CheckTorchBurnout(world, other, true));
	}

	// Interleaved positions must keep independent counts.
	CHECK(!RedstoneManager::CheckTorchBurnout(world, pos, false));
	CHECK(!RedstoneManager::CheckTorchBurnout(world, other, false));
	CHECK(RedstoneManager::CheckTorchBurnout(world, pos, true));
	CHECK(!RedstoneManager::CheckTorchBurnout(world, other, false));

	// Entries older than the 100 tick window stop counting after pruning.
	world.elapsedTicks += 101;
	RedstoneManager::PruneTorchUpdates(world);
	CHECK(!RedstoneManager::CheckTorchBurnout(world, pos, false));
	CHECK(!RedstoneManager::CheckTorchBurnout(world, other, false));
}

void TestRedstoneWireDecay() {
	WorldManager world;
	auto chunk = std::make_shared<Chunk>();
	chunk->cpos = { 0, 0 };
	chunk->state.store(ChunkState::Generated);
	for (int x = 0; x < CHUNK_WIDTH; ++x) {
		chunk->SetBlockRaw({ x, 63, 8 }, BLOCK_STONE);
		chunk->SetBlockRaw({ x, 64, 8 }, BLOCK_REDSTONE);
		chunk->SetMetaRaw({ x, 64, 8 }, 15);
	}
	world.chunks[Int32_2{ 0, 0 }] = chunk;

	// With no power source every wire drops to zero and stays there.
	RedstoneManager::RefreshWireAt(world, { 0, 64, 8 });
	for (int x = 0; x < CHUNK_WIDTH; ++x)
		CHECK_EQ(int(world.GetMetadata({ x, 64, 8 })), 0);

	RedstoneManager::RefreshWireAt(world, { 0, 64, 8 });
	for (int x = 0; x < CHUNK_WIDTH; ++x)
		CHECK_EQ(int(world.GetMetadata({ x, 64, 8 })), 0);
}

void TestRedstoneLongWire() {
	WorldManager world;
	std::vector<std::shared_ptr<Chunk>> chunks;
	for (int cx = 0; cx < 8; ++cx) {
		auto chunk = std::make_shared<Chunk>();
		chunk->cpos = { cx, 0 };
		chunk->state.store(ChunkState::Generated);
		for (int lx = 0; lx < CHUNK_WIDTH; ++lx) {
			chunk->SetBlockRaw({ lx, 63, 8 }, BLOCK_STONE);
			chunk->SetBlockRaw({ lx, 64, 8 }, BLOCK_REDSTONE);
			chunk->SetMetaRaw({ lx, 64, 8 }, 0);
		}
		world.chunks[Int32_2{ cx, 0 }] = chunk;
		chunks.push_back(std::move(chunk));
	}
	// A lever mounted on the stone under the first wire hard-powers it.
	chunks[0]->SetBlockRaw({ 0, 63, 9 }, BLOCK_LEVER);
	chunks[0]->SetMetaRaw({ 0, 63, 9 },
	                      uint8_t(GetMetaFromDirection(BLOCK_LEVER, Cardinal::Value::South) | 0b1000));

	// Solve starting at the far end so a full-pass solver only advances power
	// one cell per pass.
	RedstoneManager::RefreshWireAt(world, { 127, 64, 8 });
	for (int x = 0; x < 128; ++x) {
		const int expected = std::max(15 - x, 0);
		CHECK_EQ(int(world.GetMetadata({ x, 64, 8 })), expected);
	}

	// Removing the source must decay the entire line back to zero.
	chunks[0]->SetBlockRaw({ 0, 63, 9 }, BLOCK_AIR);
	RedstoneManager::RefreshWireAt(world, { 127, 64, 8 });
	for (int x = 0; x < 128; ++x)
		CHECK_EQ(int(world.GetMetadata({ x, 64, 8 })), 0);
}

void TestRedstoneReentrantUpdate() {
	WorldManager world;
	auto chunk = std::make_shared<Chunk>();
	chunk->cpos = { 0, 0 };
	chunk->state.store(ChunkState::Generated);
	for (int x = 0; x < 4; ++x) {
		chunk->SetBlockRaw({ x, 63, 8 }, BLOCK_STONE);
		chunk->SetBlockRaw({ x, 64, 8 }, BLOCK_REDSTONE);
	}
	// A torch with an invalid attachment. Neighbor notifications during the
	// solve break it, which synchronously triggers a nested redstone update.
	// The outer solve must not lose its scratch state when that happens.
	chunk->SetBlockRaw({ 0, 62, 8 }, BLOCK_REDSTONE_TORCH_ON);
	world.chunks[Int32_2{ 0, 0 }] = chunk;

	RedstoneManager::RefreshWireAt(world, { 3, 64, 8 });
	CHECK_EQ(int(world.GetBlockId({ 0, 62, 8 })), int(BLOCK_AIR));
	for (int x = 0; x < 4; ++x)
		CHECK_EQ(int(world.GetMetadata({ x, 64, 8 })), 0);
}

void TestChunkSenderFlushOrdering() {
	Runtime runtime;
	PlayerSession session(-1, runtime);
	ChunkSender sender;

	auto makeReady = [](Int32_2 _pos) {
		Packet::ChunkData data;
		data.pos.x = _pos.x * CHUNK_WIDTH;
		data.pos.z = _pos.z * CHUNK_WIDTH;
		data.compressedData = { 1, 2, 3, 4 };
		std::promise<Packet::ChunkData> promise;
		promise.set_value(std::move(data));
		return promise.get_future().share();
	};

	std::promise<Packet::ChunkData> pendingPromise;
	auto pendingFuture = pendingPromise.get_future().share();

	std::vector<ChunkSender::PendingChunk> queue;
	queue.push_back({ Int32_2{ 1, 0 }, makeReady({ 1, 0 }), {} });
	queue.push_back({ Int32_2{ 2, 0 }, pendingFuture, {} });
	queue.push_back({ Int32_2{ 3, 0 }, makeReady({ 3, 0 }), {} });
	sender.inFlight[&session] = queue;

	sender.Flush(session);
	CHECK_EQ(sender.inFlight[&session].size(), size_t(1));
	CHECK_EQ(sender.inFlight[&session][0].pos.x, 2);
	CHECK_EQ(session.newlyFlushed.size(), size_t(2));
	CHECK((session.newlyFlushed[0] == Int32_2{ 1, 0 }));
	CHECK((session.newlyFlushed[1] == Int32_2{ 3, 0 }));
	CHECK(session.stream.GetRawWriteBuffer().size() > 0);

	// The retained job keeps its place and flushes once it becomes ready.
	session.newlyFlushed.clear();
	Packet::ChunkData data;
	data.compressedData = { 5 };
	pendingPromise.set_value(std::move(data));
	sender.Flush(session);
	CHECK(sender.inFlight[&session].empty());
	CHECK_EQ(session.newlyFlushed.size(), size_t(1));
	CHECK((session.newlyFlushed[0] == Int32_2{ 2, 0 }));
}

