void TestCommandParsing() {
	struct ParsedResult {
		bool called = false;
		strategos::Vec3 pos{};
		std::string first;
		std::string second;
		int number = 0;
	};

	strategos::BrigadierContext dispatcher;
	auto allow = [](void*) { return true; };

	dispatcher.add_command(
	    strategos::Node::literal("tp")
	        .op()
	        .then(strategos::Node::vec3("pos").executes([](const strategos::CmdNode& _cmd, void* _ud) {
		        auto* out = static_cast<ParsedResult*>(_ud);
		        out->called = true;
		        if (auto pos = _cmd.get_arg<strategos::Vec3>("pos"))
			        out->pos = *pos;
		        return std::string{};
	        }))
	        .then(strategos::Node::string("player")
	                  .then(strategos::Node::vec3("pos").executes([](const strategos::CmdNode& _cmd, void* _ud) {
		                  auto* out = static_cast<ParsedResult*>(_ud);
		                  out->called = true;
		                  out->first = _cmd.get_arg<std::string>("player").value_or("");
		                  if (auto pos = _cmd.get_arg<strategos::Vec3>("pos"))
			                  out->pos = *pos;
		                  return std::string{};
	                  }))
	                  .then(strategos::Node::string("target").executes([](const strategos::CmdNode& _cmd, void* _ud) {
		                  auto* out = static_cast<ParsedResult*>(_ud);
		                  out->called = true;
		                  out->first = _cmd.get_arg<std::string>("player").value_or("");
		                  out->second = _cmd.get_arg<std::string>("target").value_or("");
		                  return std::string{};
	                  }))));
	dispatcher.add_command(strategos::Node::literal("num").then(
	    strategos::Node::integer("n", 0, 10).executes([](const strategos::CmdNode& _cmd, void* _ud) {
		    auto* out = static_cast<ParsedResult*>(_ud);
		    out->called = true;
		    out->number = _cmd.get_arg<int>("n").value_or(-1);
		    return std::string{};
	    })));

	ParsedResult coords;
	auto coordResult = dispatcher.execute("tp 1.5 64 ~-2", &coords, allow);
	CHECK(coordResult.has_value());
	CHECK(coords.called);
	CHECK_EQ(coords.pos.pos[0], 1.5f);
	CHECK_EQ(coords.pos.pos[1], 64.0f);
	CHECK_EQ(coords.pos.pos[2], -2.0f);
	CHECK(coords.pos.is_relative(strategos::Axis::Z));
	CHECK(!coords.pos.is_relative(strategos::Axis::X));

	ParsedResult named;
	auto namedResult = dispatcher.execute("tp Alice Bob", &named, allow);
	CHECK(namedResult.has_value());
	CHECK(named.called);
	CHECK_EQ(named.first, std::string("Alice"));
	CHECK_EQ(named.second, std::string("Bob"));

	ParsedResult mixed;
	auto mixedResult = dispatcher.execute("tp Alice 1 2 3", &mixed, allow);
	CHECK(mixedResult.has_value());
	CHECK(mixed.called);
	CHECK_EQ(mixed.first, std::string("Alice"));
	CHECK_EQ(mixed.pos.pos[0], 1.0f);
	CHECK_EQ(mixed.pos.pos[1], 2.0f);
	CHECK_EQ(mixed.pos.pos[2], 3.0f);

	ParsedResult number;
	auto numberResult = dispatcher.execute("num +7", &number, allow);
	CHECK(numberResult.has_value());
	CHECK_EQ(number.number, 7);

	number.called = false;
	auto outOfRange = dispatcher.execute("num 11", &number, allow);
	CHECK(!outOfRange.has_value());
	CHECK_EQ(int(outOfRange.error().error), int(strategos::ParseError::InvalidToken));
	CHECK(!number.called);

	auto unknown = dispatcher.execute("num abc", &number, allow);
	CHECK(!unknown.has_value());
	CHECK_EQ(int(unknown.error().error), int(strategos::ParseError::UnknownCommand));

	auto incomplete = dispatcher.execute("tp", &number, allow);
	CHECK(!incomplete.has_value());
	CHECK_EQ(int(incomplete.error().error), int(strategos::ParseError::IncompleteCommand));
}

void TestInventoryTickDiff() {
	Inventory inventory(45);
	InventoryInteraction interaction(&inventory);
	interaction.InitSnapshot();

	auto unchanged = interaction.TickDiff();
	CHECK(unchanged.empty());

	inventory.slots[7] = ItemStack{ ItemId(5), 3, 1 };
	auto changed = interaction.TickDiff();
	CHECK_EQ(changed.size(), size_t(1));
	CHECK_EQ(changed[0].slot, 7);
	CHECK_EQ(changed[0].stack.id, ItemId(5));
	CHECK_EQ(int(changed[0].stack.count), 3);

	// The snapshot advanced, so an immediate second diff is empty.
	CHECK(interaction.TickDiff().empty());

	// Multiple changes are reported in slot order.
	inventory.slots[7] = ItemStack{};
	inventory.slots[8] = ItemStack{ ItemId(6), 1, 0 };
	auto multiple = interaction.TickDiff();
	CHECK_EQ(multiple.size(), size_t(2));
	CHECK_EQ(multiple[0].slot, 7);
	CHECK_EQ(multiple[1].slot, 8);

	// The diff buffer is reused, so later ticks do not allocate again.
	const size_t capacity = interaction.diffScratch.capacity();
	CHECK(capacity >= size_t(2));
	CHECK(interaction.TickDiff().empty());
	CHECK_EQ(interaction.diffScratch.capacity(), capacity);
	inventory.slots[9] = ItemStack{ ItemId(7), 1, 0 };
	CHECK_EQ(interaction.TickDiff().size(), size_t(1));
	CHECK_EQ(interaction.diffScratch.capacity(), capacity);
}

void TestPlayerSaveQueue() {
	TempDir temp("player-save-queue");
	std::filesystem::create_directories(temp.path / "players");
	SaveManager saves;
	saves.SetSaveDirectory(temp.path.string());

	// Repeated saves for one player coalesce to a single pending payload.
	for (int i = 0; i < 100; ++i) {
		Tag data = saves.GetNewPlayerNbt();
		data.compound["Health"].shortValue = int16_t(i);
		saves.QueuePlayerNbtSave("Alice", std::move(data));
	}
	CHECK_EQ(saves.PendingPlayerSaves(), size_t(1));
	saves.PumpPlayerSaves();
	CHECK_EQ(saves.PendingPlayerSaves(), size_t(1)); // no worker yet
	saves.FlushPlayerSaves();
	CHECK_EQ(saves.PlayerSaveWriteCount(), uint64_t(1));
	CHECK_EQ(saves.PendingPlayerSaves(), size_t(0));

	auto loaded = saves.GetPlayerNbt("Alice");
	CHECK_EQ(int(loaded.Get("Health").GetShort()), 99);
	CHECK(std::filesystem::exists(temp.path / "players" / "Alice.dat"));

	// The worker path also processes one coalesced batch per pump.
	saves.StartPlayerSaveWorker();
	for (int i = 0; i < 100; ++i) {
		Tag data = saves.GetNewPlayerNbt();
		data.compound["Health"].shortValue = int16_t(200 + i);
		saves.QueuePlayerNbtSave("Bob", std::move(data));
	}
	saves.PumpPlayerSaves();
	saves.FlushPlayerSaves();
	CHECK_EQ(saves.PlayerSaveWriteCount(), uint64_t(2));

	auto bob = saves.GetPlayerNbt("Bob");
	CHECK_EQ(int(bob.Get("Health").GetShort()), 299);
}

void TestUnlightEarlyOut() {
	WorldManager world;
	for (int dx = -1; dx <= 1; ++dx) {
		for (int dz = -1; dz <= 1; ++dz) {
			auto chunk = std::make_shared<Chunk>();
			chunk->cpos = { dx, dz };
			chunk->state.store(ChunkState::Generated);
			world.chunks[Int32_2{ dx, dz }] = std::move(chunk);
		}
	}
	auto& center = world.chunks[Int32_2{ 0, 0 }];
	center->SetBlockRaw({ 8, 64, 8 }, BLOCK_STONE);

	// Block light is already zero here, so nothing should change.
	world.lightManager.UnlightAt(8, 64, 8, LightType::Block, world);
	CHECK_EQ(int(center->GetBlockLight({ 8, 64, 8 })), 0);

	// Non-zero light still goes through the full unlight path.
	center->SetSkyLight({ 8, 64, 8 }, 15);
	world.lightManager.UnlightAt(8, 64, 8, LightType::Sky, world);
	CHECK_EQ(int(center->GetSkyLight({ 8, 64, 8 })), 0);
}

void TestRandomTickCache() {
	WorldManager world;
	world.SetViewRadius(4); // simulation radius 4 => 9x9 candidate square

	std::vector<ClientPosition> players(1);
	players[0].pos = { 8.0, 64.0, 8.0 }; // chunk (0, 0)
	world.PerformRandomTicks(players);
	CHECK_EQ(world.RandomTickCandidateCount(), size_t(81));
	CHECK_EQ(world.RandomTickRebuildCount(), size_t(1));

	// Stationary players reuse the cached set.
	world.PerformRandomTicks(players);
	CHECK_EQ(world.RandomTickCandidateCount(), size_t(81));
	CHECK_EQ(world.RandomTickRebuildCount(), size_t(1));

	// Changing the player's chunk rebuilds it.
	players[0].pos.x = 40.0; // chunk (2, 0)
	world.PerformRandomTicks(players);
	CHECK_EQ(world.RandomTickRebuildCount(), size_t(2));

	// A second, partially overlapping player is deduplicated.
	players.push_back(ClientPosition{ .pos = { 136.0, 64.0, 8.0 } }); // chunk (8, 0)
	world.PerformRandomTicks(players);
	CHECK_EQ(world.RandomTickRebuildCount(), size_t(3));
	CHECK_EQ(world.RandomTickCandidateCount(), size_t(135));

	// A simulation radius change also rebuilds.
	world.SetViewRadius(3);
	world.PerformRandomTicks(players);
	CHECK_EQ(world.RandomTickRebuildCount(), size_t(4));
	CHECK_EQ(world.RandomTickCandidateCount(), size_t(91));
}

void TestLoadedChunkClimateBaked() {
	TempDir temp("climate-load");
	const auto regionDir = temp.path / "region";
	std::filesystem::create_directories(regionDir);
	RegionManager regions;
	CHECK(regions.Initialize(regionDir.string()));

	WorldManager world;
	world.InitWorldSeed(int64_t(1234));
	regions.world = &world;
	world.regionManager = &regions;

	auto chunk = std::make_shared<Chunk>();
	chunk->cpos = { 0, 0 };
	OverworldGenerator gen(1234);
	gen.GenerateChunk(*chunk);
	chunk->GenerateSkylightMap();
	regions.SaveChunk(chunk, false);
	regions.FlushAll();

	regions.LoadChunk(Int32_2{ 0, 0 });
	regions.iopool.wait();
	auto loaded = regions.GetChunk(Int32_2{ 0, 0 });
	CHECK(loaded != nullptr);
	if (loaded) {
		CHECK(loaded->climateBaked);
		CHECK_EQ(loaded->cpos.x, 0);
		CHECK_EQ(loaded->cpos.z, 0);

		// The first biome lookup after a load is now a cached read.
		world.chunks[Int32_2{ 0, 0 }] = loaded;
		CHECK(loaded->climateBaked);
		const int biome = int(world.GetBiome({ 8, 8 }));
		CHECK(biome >= int(Biome::BIOME_RAINFOREST) || biome >= 0);
		CHECK(loaded->climateBaked);
	}

	// Nether worlds have no climate to bake.
	WorldManager hellWorld(true);
	hellWorld.InitWorldSeed(int64_t(1234));
	regions.world = &hellWorld;
	regions.LoadChunk(Int32_2{ 0, 0 });
	regions.iopool.wait();
	auto hellLoaded = regions.GetChunk(Int32_2{ 0, 0 });
	CHECK(hellLoaded != nullptr);
	if (hellLoaded)
		CHECK(!hellLoaded->climateBaked);

	regions.Release();
}

void TestSendChatFastPath() {
	Runtime runtime;
	PlayerSession session(-1, runtime);

	auto decodeMessages = [](const std::vector<uint8_t>& bytes) {
		std::vector<std::string> out;
		NetworkStream in(-1);
		in.AppendReadData(bytes.data(), bytes.size());
		while (in.Mark() < bytes.size()) {
			CHECK_EQ(int(in.Read<PacketId>()), int(PacketId::ChatMessage));
			out.push_back(in.ReadString16());
		}
		return out;
	};
	auto send = [&](const std::string& _message) {
		session.stream.ClearWriteBuffer();
		SendChat(session, _message);
		const auto bytes = session.stream.GetRawWriteBuffer();
		return decodeMessages(bytes);
	};

	CHECK(send("").empty());

	auto shortAscii = send("Teleported Steve");
	CHECK_EQ(shortAscii.size(), size_t(1));
	CHECK_EQ(shortAscii[0], std::string("Teleported Steve"));

	auto colored = send("§eHello world");
	CHECK_EQ(colored.size(), size_t(1));
	CHECK_EQ(colored[0], std::string("§eHello world"));

	const std::string longAscii(300, 'a');
	auto chunks = send(longAscii);
	CHECK_EQ(chunks.size(), size_t(3));
	CHECK_EQ(chunks[0].size(), size_t(119));
	CHECK_EQ(chunks[1].size(), size_t(119));
	CHECK_EQ(chunks[2].size(), size_t(62));
	std::string rebuilt;
	for (auto& part : chunks)
		rebuilt += part;
	CHECK_EQ(rebuilt, longAscii);

	// Color prefixes repeat on continuation chunks like the old path.
	const std::string coloredLong = "§e" + std::string(200, 'b');
	auto coloredChunks = send(coloredLong);
	CHECK_EQ(coloredChunks.size(), size_t(2));
	CHECK_EQ(coloredChunks[0], coloredLong.substr(0, coloredChunks[0].size()));
	CHECK(coloredChunks[1].starts_with("§e"));

	// Non-simple text still uses the UCS-2 path and round-trips.
	auto unicode = send("héllo ☃");
	CHECK_EQ(unicode.size(), size_t(1));
	CHECK_EQ(unicode[0], std::string("héllo ☃"));
}

