void TestString16IntoReuse() {
	NetworkStream out(-1);
	const std::string longText(200, 'a');
	out.WriteString16(longText);
	out.WriteString16("héllo ☃");
	const auto& bytes = out.GetRawWriteBuffer();

	NetworkStream in(-1);
	in.AppendReadData(bytes.data(), bytes.size());
	std::string buffer;
	in.ReadString16Into(buffer);
	CHECK_EQ(buffer, longText);
	const size_t capacity = buffer.capacity();
	in.ReadString16Into(buffer);
	CHECK_EQ(buffer, std::string("héllo ☃"));
	CHECK_EQ(buffer.capacity(), capacity);
	CHECK(!in.IsShortRead());

	// A short read clears the output and must not leave a partial message.
	NetworkStream partial(-1);
	partial.WriteString16("abc");
	const auto partialBytes = partial.GetRawWriteBuffer();
	NetworkStream shortIn(-1);
	shortIn.AppendReadData(partialBytes.data(), 3);
	buffer = "stale";
	shortIn.ReadString16Into(buffer);
	CHECK(buffer.empty());
	CHECK(shortIn.IsShortRead());
}

void TestPacketRoundTrips() {
	// Round-trip through an in-memory buffer using the same read/write path as
	// a socket, so serializer and deserializer must agree on the wire layout.
	auto roundTrip = [](Packet::BasePacket& _packet, Packet::BasePacket& _decoded) {
		NetworkStream out(-1);
		_packet.Serialize(out);
		const auto& bytes = out.GetRawWriteBuffer();

		NetworkStream in(-1);
		in.AppendReadData(bytes.data(), bytes.size());
		// The dispatcher consumes the packet id before calling Deserialize.
		CHECK_EQ(int(in.Read<PacketId>()), int(bytes[0]));
		_decoded.Deserialize(in);
		CHECK(!in.IsShortRead());
		CHECK_EQ(in.Mark(), bytes.size());
	};

	Packet::PlayerPosition position;
	position.position = { 123.25, 64.5, -456.75 };
	position.cameraY = 66.12;
	position.onGround = true;
	Packet::PlayerPosition positionDecoded;
	roundTrip(position, positionDecoded);
	CHECK_EQ(positionDecoded.position.x, 123.25);
	CHECK_EQ(positionDecoded.position.y, 64.5);
	CHECK_EQ(positionDecoded.position.z, -456.75);
	CHECK_EQ(positionDecoded.cameraY, 66.12);
	CHECK(positionDecoded.onGround);

	Packet::ChatMessage chat;
	chat.message = "héllo ☃ world";
	Packet::ChatMessage chatDecoded;
	roundTrip(chat, chatDecoded);
	CHECK_EQ(chatDecoded.message, std::string("héllo ☃ world"));

	Packet::SetBlock block;
	block.position = { 12, 64, -7 };
	block.block = { BLOCK_STONE, 3 };
	Packet::SetBlock blockDecoded;
	roundTrip(block, blockDecoded);
	CHECK_EQ(blockDecoded.position.x, int32_t(12));
	CHECK_EQ(int(blockDecoded.position.y), 64);
	CHECK_EQ(blockDecoded.position.z, int32_t(-7));
	CHECK_EQ(int(blockDecoded.block.type), int(BLOCK_STONE));
	CHECK_EQ(int(blockDecoded.block.data), 3);
}

void TestNetworkStream() {
#if defined(BPP_HAS_POSIX_SOCKETS)
	int fds[2] = { -1, -1 };
	CHECK_EQ(::socketpair(AF_UNIX, SOCK_STREAM, 0, fds), 0);
	if (fds[0] < 0 || fds[1] < 0)
		return;
	const int flags = ::fcntl(fds[1], F_GETFL, 0);
	::fcntl(fds[1], F_SETFL, flags | O_NONBLOCK);

	NetworkStream writer(fds[0]);
	NetworkStream reader(fds[1]);
	writer.Write<uint16_t>(0x1234);
	writer.WriteString8("hello");
	writer.WriteString16("héllo ☃");
	writer.Write<uint32_t>(0xDEADBEEF);
	CHECK(writer.FlushWriteBuffer());
	reader.DrainToBuffer();

	CHECK_EQ(reader.Read<uint16_t>(), uint16_t(0x1234));
	CHECK_EQ(reader.ReadString8(), std::string("hello"));
	CHECK_EQ(reader.ReadString16(), std::string("héllo ☃"));
	CHECK_EQ(reader.Read<uint32_t>(), uint32_t(0xDEADBEEF));
	CHECK(!reader.IsShortRead());
	CHECK(!reader.HasData());

	// A short read must be recoverable via Mark()/Rollback().
	writer.Write<uint32_t>(0x01020304);
	writer.FlushWriteBuffer();
	reader.DrainToBuffer();
	const size_t mark = reader.Mark();
	CHECK_EQ(reader.Read<uint32_t>(), uint32_t(0x01020304));
	reader.Rollback(mark);
	CHECK_EQ(reader.Read<uint32_t>(), uint32_t(0x01020304));

	// String-16 bodies split across two ticks must also roll back cleanly.
	NetworkStream encoded(-1);
	encoded.WriteString16("abc");
	const auto serialized = encoded.GetRawWriteBuffer();
	CHECK(serialized.size() > 4);
	::send(fds[0], serialized.data(), 4, 0);
	reader.DrainToBuffer();
	const size_t stringMark = reader.Mark();
	CHECK(reader.ReadString16().empty());
	CHECK(reader.IsShortRead());
	reader.Rollback(stringMark);
	::send(fds[0], serialized.data() + 4, serialized.size() - 4, 0);
	reader.DrainToBuffer();
	CHECK_EQ(reader.ReadString16(), std::string("abc"));
	CHECK(!reader.IsShortRead());

	// A non-blocking flush that only sends part of a large buffer must keep
	// the unsent tail intact and eventually deliver every byte exactly once.
	int bigFds[2] = { -1, -1 };
	CHECK_EQ(::socketpair(AF_UNIX, SOCK_STREAM, 0, bigFds), 0);
	if (bigFds[0] < 0 || bigFds[1] < 0)
		return;
	::fcntl(bigFds[0], F_SETFL, ::fcntl(bigFds[0], F_GETFL, 0) | O_NONBLOCK);
	::fcntl(bigFds[1], F_SETFL, ::fcntl(bigFds[1], F_GETFL, 0) | O_NONBLOCK);
	int sendBufferSize = 4096;
	::setsockopt(bigFds[0], SOL_SOCKET, SO_SNDBUF, &sendBufferSize, sizeof(sendBufferSize));
	{
		NetworkStream sender(bigFds[0]);
		std::vector<uint8_t> payload(512 * 1024);
		for (size_t i = 0; i < payload.size(); ++i)
			payload[i] = uint8_t(i * 31 + 7);
		sender.WriteBytes(payload.data(), payload.size());
		CHECK_EQ(sender.GetRawWriteBuffer().size(), payload.size());

		std::vector<uint8_t> received;
		received.reserve(payload.size());
		for (int spin = 0; spin < 10000 && received.size() < payload.size(); ++spin) {
			uint8_t chunk[8192];
			for (;;) {
				const ssize_t n = ::recv(bigFds[1], chunk, sizeof(chunk), 0);
				if (n <= 0)
					break;
				received.insert(received.end(), chunk, chunk + n);
			}
			sender.FlushWriteBuffer();
		}
		CHECK(received == payload);
		CHECK(sender.GetRawWriteBuffer().empty());
	}
#endif
}

