volatile size_t benchSink = 0;

template <typename F>
void Bench(const char* _name, size_t _bytesPerOp, F&& _fn) {
	// Warm up before timing.
	for (int i = 0; i < 3; ++i)
		benchSink += _fn();

	size_t iterations = 0;
	const auto start = std::chrono::steady_clock::now();
	double elapsed = 0.0;
	do {
		benchSink += _fn();
		++iterations;
		elapsed = std::chrono::duration<double>(std::chrono::steady_clock::now() - start).count();
	} while (elapsed < 0.25 && iterations < 1000000);

	const double nsPerOp = elapsed * 1e9 / double(iterations);
	const double mbPerSecond = _bytesPerOp ? (double(_bytesPerOp) * double(iterations) / (1024.0 * 1024.0)) / elapsed
	                                       : 0.0;
	std::cout << std::format("BENCH {:<30} ops={:<9} ns/op={:<12.1f} mb/s={:.1f}\n", _name, iterations, nsPerOp,
	                         mbPerSecond);
}

